public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] A = new int[N];
        int[] B = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
            B[i] = sc.nextInt();
        }

        int INF = 1_000_000_000;
        // dp[mask] = minimal number of swaps to arrange first k cards (k = popcount(mask))
        // where mask indicates which of the first N cards are flipped.
        int[] dp = new int[1 << N];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int mask = 0; mask < (1 << N); mask++) {
            int k = Integer.bitCount(mask);
            if (dp[mask] == INF) continue;
            for (int i = 0; i < N; i++) {
                if ((mask & (1 << i)) == 0) {
                    // Try to place card i at position k (0-indexed)
                    int value = (k % 2 == 0) ? A[i] : B[i]; // parity decides which side up
                    // Check if it can be placed after last placed card
                    int lastVal = -1;
                    if (k > 0) {
                        // find last placed card
                        int lastIdx = -1;
                        for (int j = 0; j < N; j++) {
                            if ((mask & (1 << j)) != 0) {
                                lastIdx = j;
                            }
                        }
                        lastVal = ((k - 1) % 2 == 0) ? A[lastIdx] : B[lastIdx];
                    }
                    if (k == 0 || value >= lastVal) {
                        // Count how many unused cards are before i
                        int swaps = 0;
                        for (int j = 0; j < i; j++) {
                            if ((mask & (1 << j)) == 0) {
                                swaps++;
                            }
                        }
                        int newMask = mask | (1 << i);
                        dp[newMask] = Math.min(dp[newMask], dp[mask] + swaps);
                    }
                }
            }
        }

        int ans = INF;
        for (int mask = 0; mask < (1 << N); mask++) {
            if (Integer.bitCount(mask) == N) {
                ans = Math.min(ans, dp[mask]);
            }
        }
        System.out.println(ans == INF ? -1 : ans);
    }
}

