        long[] dp = new long[1<<N];
        int[] lastVal = new int[1<<N];
        Arrays.fill(dp, Long.MAX_VALUE/2);
        dp[0]=0; lastVal[0]=0;
        for(int mask=0;mask<(1<<N);mask++){
            if(dp[mask]==Long.MAX_VALUE/2) continue;
            int j=Integer.bitCount(mask)+1; // next position (1-indexed)
