                if((mask&(1<<(c-1)))!=0) continue;
                int val=((c+j)%2==0)?A[c]:B[c];
                if(val<lastVal[mask]) continue;
                int newmask=mask|(1<<(c-1));
                // inversions added = number of cards already placed with original index > c... 
                // actually inversions = number of bits set in mask that are > c-1
                int inv=Integer.bitCount(mask>>c); // cards with index > c already placed
