import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Card {
        long a, b;
        Card(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    static final long INF = (long) 4e18;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        Card[] cards = new Card[N];
        for (int i = 0; i < N; i++) {
            long a = fs.nextLong();
            long b = fs.nextLong();
            cards[i] = new Card(a, b);
        }

        // dp[mask][last][parity]
        // parity = 0 if the last card is red side up, 1 if blue side up
        // cost = minimum number of operations needed
        int M = 1 << N;
        long[][][] dp = new long[M][N][2];
        for (int mask = 0; mask < M; mask++) {
            for (int i = 0; i < N; i++) {
                dp[mask][i][0] = INF;
                dp[mask][i][1] = INF;
            }
        }

        // Start with choosing first card in final sequence.
        // If card i moves to position 0, it crosses i cards, so it flips i times.
        for (int i = 0; i < N; i++) {
            int parity = i & 1;
            dp[1 << i][i][parity] = i;
        }

        for (int mask = 1; mask < M; mask++) {
            int placed = Integer.bitCount(mask);

            for (int last = 0; last < N; last++) {
                for (int pLast = 0; pLast < 2; pLast++) {
                    long cur = dp[mask][last][pLast];
                    if (cur >= INF) continue;

                    long lastVal = (pLast == 0 ? cards[last].a : cards[last].b);

                    for (int nxt = 0; nxt < N; nxt++) {
                        if ((mask & (1 << nxt)) != 0) continue;

                        // Number of swaps needed when placing nxt after current placed cards:
                        // among original positions before nxt, count how many are not yet used
                        int usedBefore = Integer.bitCount(mask & ((1 << nxt) - 1));
                        int swaps = nxt - usedBefore;

                        int pNxt = swaps & 1; // red if even flips, blue if odd flips
                        long nxtVal = (pNxt == 0 ? cards[nxt].a : cards[nxt].b);

                        if (lastVal <= nxtVal) {
                            int nmask = mask | (1 << nxt);
                            long nv = cur + swaps;
                            if (nv < dp[nmask][nxt][pNxt]) {
                                dp[nmask][nxt][pNxt] = nv;
                            }
                        }
                    }
                }
            }
        }

        long ans = INF;
        int full = M - 1;
        for (int last = 0; last < N; last++) {
            for (int p = 0; p < 2; p++) {
                ans = Math.min(ans, dp[full][last][p]);
            }
        }

        System.out.println(ans >= INF ? -1 : ans);
    }
}

