    // Try starting with A[0] or B[0] as first element
    for (int start : {0, 1}) {
        // We'll try to build sequence greedily
        // Keep track of which cards are used and final positions
        vector<int> used(N, 0);
        vector<int> seq; // values in final order
        vector<int> cardIdx; // original card index in final order

        int cur = start;
        bool ok = true;
        for (int pos = 0; pos < N; pos++) {
            int bestVal = INF;
            int bestIdx = -1;
            int bestFlip = -1; // 0 for A, 1 for B
            for (int i = 0; i < N; i++) {
                if (used[i]) continue;
                // parity: if (pos - current position in original) % 2 determines flip
                // But we don't know final position yet. Instead we directly try values.
                // Actually we can choose either A[i] or B[i] if parity matches accumulated flips.
                // The parity constraint: each move flips both.
                // At final position pos, the number of moves card i made = |finalPos - i|
                // parity of moves = (pos - i) mod 2 (depending on direction, but parity same)
                // If parity even -> show A[i]; odd -> show B[i]
                int distParity = (pos - i) & 1; // parity of moves
                if (distParity < 0) distParity = -distParity;
                distParity &= 1;
                int val;
                int flip;
                if (distParity == 0) {
                    val = A[i];
                    flip = 0;
                } else {
                    val = B[i];
                    flip = 1;
                }
                if (val < bestVal && val >= (seq.empty() ? -INF : seq.back())) {
                    bestVal = val;
                    bestIdx = i;
                    bestFlip = flip;
                }
            }
            if (bestIdx == -1) {
                ok = false;
                break;
            }
            used[bestIdx] = 1;
            seq.push_back(bestVal);
            cardIdx.push_back(bestIdx);
        }
        if (!ok) continue;

        // Now compute minimal adjacent swaps to achieve this order
        // We need to transform [0,1,...,N-1] to cardIdx
        // Use BIT for inversion count
        vector<int> posInOriginal(N);
        for (int i = 0; i < N; i++) posInOriginal[cardIdx[i]] = i;
        // Count inversions in posInOriginal to get swaps
        int swaps = 0;
        vector<int> bit(N+1, 0);
        auto add = [&](int idx, int val) {
            for (++idx; idx <= N; idx += idx & -idx) bit[idx] += val;
        };
        auto sum = [&](int idx) {
            int res = 0;
            for (++idx; idx > 0; idx -= idx & -idx) res += bit[idx];
            return res;
        };
        for (int i = N-1; i >= 0; i--) {
            swaps += sum(posInOriginal[i]);
            add(posInOriginal[i], 1);
        }
        ans = min(ans, swaps);
    }

    if (ans == INF) cout << -1 << "\n";
    else cout << ans << "\n";

    return 0;
}

