#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N), B(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    for (int i = 0; i < N; ++i) cin >> B[i];

    const long long INF = (1LL << 60);

    // dp[mask][last][p]
    // mask: chosen original indices
    // last: original index placed at the end
    // p: parity of inversions so far (0/1)
    //
    // Cost = number of adjacent swaps = inversions.
    // Final visible value of original card i placed at position pos:
    //   A[i] if (i % 2) == (pos % 2)
    //   B[i] otherwise
    //
    // Since each adjacent swap flips both cards, a card is flipped
    // exactly parity(number of swaps involving it) times.
    // This parity equals parity(|i-pos|), i.e. i%2 xor pos%2.
    //
    // We build the final permutation from left to right.
    // If we append card j after having chosen popcount(mask)=k cards,
    // then its final position is k.
    // Additional inversions added are the number of already-unpicked
    // indices smaller than j:
    //   add = count(i < j, i not in mask)
    // so inversion parity updates by add%2, and total cost adds add.

    int M = 1 << N;
    vector<vector<array<long long,2>>> dp(M, vector<array<long long,2>>(N, {INF, INF}));

    auto value_at = [&](int idx, int pos) -> long long {
        return ((idx & 1) == (pos & 1)) ? A[idx] : B[idx];
    };

    for (int i = 0; i < N; ++i) {
        int mask = 1 << i;
        long long v = value_at(i, 0);
        (void)v; // only for symmetry; no previous constraint
        int add = i; // with empty mask, count of unpicked smaller than i is i
        dp[mask][i][add & 1] = add;
    }

    for (int mask = 1; mask < M; ++mask) {
        int k = __builtin_popcount((unsigned)mask);
        if (k == N) continue;

        for (int last = 0; last < N; ++last) {
            for (int par = 0; par < 2; ++par) {
                long long cur = dp[mask][last][par];
                if (cur == INF) continue;

                long long lastVal = value_at(last, k - 1);

                for (int nxt = 0; nxt < N; ++nxt) {
                    if (mask & (1 << nxt)) continue;

                    long long nxtVal = value_at(nxt, k);
                    if (lastVal > nxtVal) continue;

                    int chosenLess = __builtin_popcount((unsigned)(mask & ((1 << nxt) - 1)));
                    int add = nxt - chosenLess; // unpicked smaller indices
                    int npar = par ^ (add & 1);
                    int nmask = mask | (1 << nxt);
                    dp[nmask][nxt][npar] = min(dp[nmask][nxt][npar], cur + add);
                }
            }
        }
    }

    long long ans = INF;
    int full = M - 1;
    for (int last = 0; last < N; ++last) {
        for (int par = 0; par < 2; ++par) {
            ans = min(ans, dp[full][last][par]);
        }
    }

    if (ans == INF) ans = -1;
    cout << ans << '\n';
    return 0;
}

