#define INF ((long long)4e18)

static inline long long llmin(long long a, long long b) { return a < b ? a : b; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long *A = (long long *)malloc((N + 1) * sizeof(long long));
    long long *B = (long long *)malloc((N + 1) * sizeof(long long));
    for (int i = 1; i <= N; i++) scanf("%lld", &A[i]);
    for (int i = 1; i <= N; i++) scanf("%lld", &B[i]);

    /*
      DP over subsets:
      dp[S][last] = minimum cost to build the first |S| positions using cards in S,
      with card 'last' placed at the end of the current prefix.

      If card i is placed at final position p (1-indexed), then:
      - it is flipped exactly parity(|i - p|) times
      - shown value is A[i] if parity even, B[i] if parity odd

      Transition cost:
      when adding card i as the next element after building subset S of size k-1,
      among remaining cards, choosing i means it must pass over all remaining cards
      with index < i. Count = i - 1 - (# chosen cards among 1..i-1).
    */

    int M = 1 << N;

    long long *dp = (long long *)malloc((size_t)M * N * sizeof(long long));
    if (!dp) return 0;
    for (int s = 0; s < M * N; s++) dp[s] = INF;

    int *pop = (int *)malloc(M * sizeof(int));
    pop[0] = 0;
    for (int s = 1; s < M; s++) pop[s] = pop[s >> 1] + (s & 1);

    // prefix count helper via bitmask popcount on lower bits
    for (int i = 0; i < N; i++) {
        int S = 1 << i;
        // position 1
        long long val = ((abs((i + 1) - 1) & 1) == 0) ? A[i + 1] : B[i + 1];
        (void)val; // actual value checked during transitions / final DP
        dp[S * N + i] = i; // cards 1..i pass over this card initially
    }

    for (int S = 1; S < M; S++) {
        int k = pop[S];
        for (int last = 0; last < N; last++) {
            long long cur = dp[S * N + last];
            if (cur >= INF) continue;

            long long lastVal = (((abs((last + 1) - k)) & 1) == 0) ? A[last + 1] : B[last + 1];

            for (int ni = 0; ni < N; ni++) {
                if (S & (1 << ni)) continue;

                int nk = k + 1;
                long long newVal = (((abs((ni + 1) - nk)) & 1) == 0) ? A[ni + 1] : B[ni + 1];
                if (lastVal > newVal) continue;

                int lowerMask = (1 << ni) - 1;
                int chosenBefore = pop[S & lowerMask];
                long long add = ni - chosenBefore;

                int NS = S | (1 << ni);
                long long *cell = &dp[NS * N + ni];
                if (cur + add < *cell) *cell = cur + add;
            }
        }
    }

    long long ans = INF;
    int full = M - 1;
    for (int last = 0; last < N; last++) {
        ans = llmin(ans, dp[full * N + last]);
    }

    if (ans >= INF) printf("-1\n");
    else printf("%lld\n", ans);

    free(A);
    free(B);
    free(dp);
    free(pop);
    return 0;
}
